), 0) AND NOT coalesce(json_type(rest, '$.pre_affected.lane_s') IN ('real', 'integer'), 0) AND NOT coalesce(json_type(rest, '$.pre_run.wait_s') IN ('real', 'integer'), 0) AND NOT coalesce(json_type(rest, '$.pre_run.run_s') IN ('real', 'integer'), 0) AND NOT coalesce(json_type(rest, '$.pre_run.limit_s') IN ('real', 'integer'), 0) AND NOT coalesce(json_type(rest, '$.pre_run.cpu_s') IN ('real', 'integer'), 0) AND NOT coalesce(json_type(rest, '$.pre_run.remote.worker_s') IN ('real', 'integer'), 0) AND NOT coalesce(json_type(rest, '$.pre_run.remote.mac_s') IN ('real', 'integer'), 0) AND NOT coalesce(json_type(rest, '$.pre_run.remote.mac_est_s') IN ('real', 'integer'), 0) AND NOT coalesce(json_type(rest, '$.pre_run.remote.rerun_s') IN ('real', 'integer'), 0) AND NOT coalesce(json_type(rest, '$.pre_run.remote.saved_s') IN ('real', 'integer'), 0) AND NOT coalesce(json_type(rest, '$.pre_run.remote.t0') IN ('real', 'integer'), 0) AND NOT coalesce(json_type(rest, '$.slot_wait_by_class.short') IN ('real', 'integer'), 0) AND NOT coalesce(json_type(rest, '$.slot_wait_by_class.land') IN ('real', 'integer'), 0) AND NOT coalesce(json_type(rest, '$.slot_wait_by_class.pre') IN ('real', 'integer'), 0) AND NOT coalesce(json_type(rest, '$.slot_wait_by_class.work') IN ('real', 'integer'), 0) AND NOT coalesce(json_type(rest, '$.batch.items') IN ('integer'), 0) AND NOT coalesce(json_type(rest, '$.batch.gates') IN ('integer'), 0) AND NOT coalesce(json_type(rest, '$.pre_affected.tests') IN ('integer'), 0) AND NOT coalesce(json_type(rest, '$.pre_run.workers') IN ('integer'), 0) AND NOT coalesce(json_type(rest, '$.pre_run.remote.tests') IN ('integer'), 0) AND NOT coalesce(json_type(rest, '$.cov_risk.lines') IN ('integer'), 0) AND NOT coalesce(json_type(rest, '$.early') IN ('true', 'false'), 0) AND NOT coalesce(json_type(rest, '$.recorded') IN ('true', 'false'), 0) AND NOT coalesce(json_type(rest, '$.pre_run.remote.fresh') IN ('true', 'false'), 0) AND json_type(rest, '$.item') IS NULL AND json_type(rest, '$.sha') IS NULL AND json_type(rest, '$.enqueued') IS NULL AND json_type(rest, '$.repo') IS NULL AND json_type(rest, '$.mode') IS NULL AND json_type(rest, '$.state') IS NULL AND json_type(rest, '$.attempt') IS NULL AND json_type(rest, '$.requested') IS NULL AND json_type(rest, '$.started') IS NULL AND json_type(rest, '$.finished') IS NULL AND json_type(rest, '$.k') IS NULL));
CREATE TABLE land_lists(queue TEXT NOT NULL, run TEXT NOT NULL, kind TEXT NOT NULL CHECK (kind IN ('guard', 'red_test', 'red_log')), ord INTEGER NOT NULL, value TEXT NOT NULL, at REAL NOT NULL, PRIMARY KEY (queue, run, kind, ord)) STRICT, WITHOUT ROWID;
CREATE INDEX land_lists_value ON land_lists(kind, value);
CREATE INDEX land_lists_at ON land_lists(at);
CREATE TABLE land_flakes(queue TEXT NOT NULL, run TEXT NOT NULL, ord INTEGER NOT NULL, test TEXT, entry TEXT, filed TEXT, at REAL NOT NULL, PRIMARY KEY (queue, run, ord)) STRICT, WITHOUT ROWID;
CREATE INDEX land_flakes_at ON land_flakes(at);
CREATE TABLE land_remote_shares(queue TEXT NOT NULL, run TEXT NOT NULL, ord INTEGER NOT NULL, host TEXT, outcome TEXT, place TEXT, mac_est_s REAL, mac_s REAL, rerun_s REAL, saved_s REAL, t0 REAL, worker_s REAL, tests INTEGER, at REAL NOT NULL, PRIMARY KEY (queue, run, ord)) STRICT, WITHOUT ROWID;
CREATE INDEX land_remote_shares_at ON land_remote_shares(at);
CREATE TABLE land_cov_carry(queue TEXT NOT NULL, run TEXT NOT NULL, ord INTEGER NOT NULL, file TEXT, text TEXT, why TEXT, line INTEGER, own INTEGER CHECK (own IN (0, 1)), measured INTEGER CHECK (measured IN (0, 1)), at REAL NOT NULL, PRIMARY KEY (queue, run, ord)) STRICT, WITHOUT ROWID;
CREATE INDEX land_cov_carry_at ON land_cov_carry(at);
CREATE TABLE land_cov_files(queue TEXT NOT NULL, run TEXT NOT NULL, path TEXT NOT NULL, said TEXT NOT NULL, at REAL NOT NULL, PRIMARY KEY (queue, run, path)) STRICT, WITHOUT ROWID;
CREATE INDEX land_cov_files_at ON land_cov_files(at);
CREATE INDEX lands_red_class ON lands(red_class, at);
CREATE TRIGGER lands_fill AFTER INSERT ON lands WHEN NEW.rest IS NULL AND json_valid(NEW.body) BEGIN
  DELETE FROM land_cov_carry WHERE queue = NEW.queue AND run = NEW.run;
  DELETE FROM land_cov_files WHERE queue = NEW.queue AND run = NEW.run;
  DELETE FROM land_flakes WHERE queue = NEW.queue AND run = NEW.run;
  DELETE FROM land_lists WHERE queue = NEW.queue AND run = NEW.run;
  DELETE FROM land_remote_shares WHERE queue = NEW.queue AND run = NEW.run;
