  UPDATE lands SET rest = json_remove(rest, '$.pre_run.remote') WHERE queue = NEW.queue AND run = NEW.run AND (rest -> '$.pre_run.remote' IN ('{}', '[]') OR json_type(rest, '$.pre_run.remote') = 'null');
