  UPDATE lands SET rest = json_remove(rest, '$.diffcov_item') WHERE queue = NEW.queue AND run = NEW.run AND (rest -> '$.diffcov_item' IN ('{}', '[]') OR json_type(rest, '$.diffcov_item') = 'null');
  UPDATE lands SET rest = json_remove(rest, '$.pre_affected') WHERE queue = NEW.queue AND run = NEW.run AND (rest -> '$.pre_affected' IN ('{}', '[]') OR json_type(rest, '$.pre_affected') = 'null');
  UPDATE lands SET rest = json_remove(rest, '$.pre_run') WHERE queue = NEW.queue AND run = NEW.run AND (rest -> '$.pre_run' IN ('{}', '[]') OR json_type(rest, '$.pre_run') = 'null');
  UPDATE lands SET rest = json_remove(rest, '$.red_cause') WHERE queue = NEW.queue AND run = NEW.run AND (rest -> '$.red_cause' IN ('{}', '[]') OR json_type(rest, '$.red_cause') = 'null');
  UPDATE lands SET rest = json_remove(rest, '$.slot_wait_by_class') WHERE queue = NEW.queue AND run = NEW.run AND (rest -> '$.slot_wait_by_class' IN ('{}', '[]') OR json_type(rest, '$.slot_wait_by_class') = 'null');
  INSERT INTO land_lists SELECT NEW.queue, NEW.run, 'guard', e.key, e.value, NEW.at FROM json_each(NEW.body, '$.guards') e WHERE (json_type(NEW.body, '$.guards') = 'array' AND NOT EXISTS (SELECT 1 FROM json_each(NEW.body, '$.guards') e WHERE e.type <> 'text'));
  INSERT INTO land_lists SELECT NEW.queue, NEW.run, 'red_test', e.key, e.value, NEW.at FROM json_each(NEW.body, '$.red_cause.tests') e WHERE (json_type(NEW.body, '$.red_cause.tests') = 'array' AND NOT EXISTS (SELECT 1 FROM json_each(NEW.body, '$.red_cause.tests') e WHERE e.type <> 'text'));
