  INSERT INTO land_cov_carry SELECT NEW.queue, NEW.run, e.key, e.value ->> '$.file', e.value ->> '$.text', e.value ->> '$.why', e.value ->> '$.line', e.value ->> '$.own', e.value ->> '$.measured', NEW.at FROM json_each(NEW.body, '$.cov_risk.carry') e WHERE (json_type(NEW.body, '$.cov_risk.carry') = 'array' AND NOT EXISTS (SELECT 1 FROM json_each(NEW.body, '$.cov_risk.carry') e WHERE e.type <> 'object' OR EXISTS (SELECT 1 FROM json_each(e.value) k WHERE k.type <> 'null' AND NOT ((k.key = 'file' AND k.type IN ('text')) OR (k.key = 'text' AND k.type IN ('text')) OR (k.key = 'why' AND k.type IN ('text')) OR (k.key = 'line' AND k.type IN ('integer')) OR (k.key = 'own' AND k.type IN ('true', 'false')) OR (k.key = 'measured' AND k.type IN ('true', 'false'))))));
