CREATE TRIGGER lands_refill AFTER UPDATE OF body ON lands WHEN NEW.rest IS NULL AND NEW.body <> '{}' AND json_valid(NEW.body) BEGIN
  DELETE FROM lands WHERE queue = NEW.queue AND run = NEW.run;
  INSERT INTO lands(queue, run, item, sha, enqueued, repo, mode, state, attempt, requested, started, finished, k, at, body) VALUES (NEW.queue, NEW.run, NEW.item, NEW.sha, NEW.enqueued, NEW.repo, NEW.mode, NEW.state, NEW.attempt, NEW.requested, NEW.started, NEW.finished, NEW.k, NEW.at, NEW.body);
END;
CREATE TRIGGER lands_bad AFTER UPDATE OF body ON lands WHEN NEW.rest IS NOT NULL AND NOT json_valid(NEW.body) BEGIN
  UPDATE lands SET rest = NULL WHERE queue = NEW.queue AND run = NEW.run;
END;
CREATE TRIGGER lands_gone AFTER DELETE ON lands BEGIN
  DELETE FROM land_cov_carry WHERE queue = OLD.queue AND run = OLD.run;
  DELETE FROM land_cov_files WHERE queue = OLD.queue AND run = OLD.run;
  DELETE FROM land_flakes WHERE queue = OLD.queue AND run = OLD.run;
  DELETE FROM land_lists WHERE queue = OLD.queue AND run = OLD.run;
  DELETE FROM land_remote_shares WHERE queue = OLD.queue AND run = OLD.run;
END;
DROP VIEW lands_v1;
CREATE VIEW lands_v1 AS SELECT run, item, sha, enqueued, repo, mode, state, attempt, requested, started, finished, k, at,
  CASE WHEN body <> '{}' THEN body ELSE json_patch(json_patch('{}', json_object('item', lands.item, 'sha', lands.sha, 'enqueued', lands.enqueued, 'repo', lands.repo, 'mode', lands.mode, 'state', lands.state, 'attempt', lands.attempt, 'requested', lands.requested, 'started', lands.started, 'finished', lands.finished, 'k', lands.k, 'landed', lands.landed, 'log', lands.log, 'why', lands.why, 'stage', lands.stage, 'cause', lands.cause, 'cause_detail', lands.cause_detail, 'k_why', lands.k_why, 'pre_affected', CASE WHEN coalesce(lands.pre_affected_ran, lands.pre_affected_took, lands.pre_affected_by, lands.pre_affected_lane_s, lands.pre_affected_tests) IS NOT NULL THEN json_object('ran', lands.pre_affected_ran, 'took', lands.pre_affected_took, 'by', lands.pre_affected_by, 'lane_s', lands.pre_affected_lane_s, 'tests', lands.pre_affected_tests) END, 'batch', CASE WHEN coalesce(lands.batch, lands.batch_items, lands.batch_gates) IS NOT NULL THEN json_object('id', lands.batch, 'items', lands.batch_items, 'gates', lands.batch_gates) END, 'pre_run', CASE WHEN coalesce(lands.pre_run_skipped, coalesce(lands.remote_outcome, lands.remote_cause, lands.remote_where, lands.remote_host, lands.remote_worker_s, lands.remote_mac_s, lands.remote_mac_est_s, lands.remote_rerun_s, lands.remote_saved_s, lands.remote_t0, lands.remote_tests, lands.remote_fresh), lands.pre_run_wait_s, lands.pre_run_run_s, lands.pre_run_limit_s, lands.pre_run_cpu_s, lands.pre_run_workers) IS NOT NULL THEN json_object('skipped', lands.pre_run_skipped, 'remote', CASE WHEN coalesce(lands.remote_outcome, lands.remote_cause, lands.remote_where, lands.remote_host, lands.remote_worker_s, lands.remote_mac_s, lands.remote_mac_est_s, lands.remote_rerun_s, lands.remote_saved_s, lands.remote_t0, lands.remote_tests, lands.remote_fresh) IS NOT NULL THEN json_object('outcome', lands.remote_outcome, 'cause', lands.remote_cause, 'where', lands.remote_where, 'host', lands.remote_host, 'worker_s', lands.remote_worker_s, 'mac_s', lands.remote_mac_s, 'mac_est_s', lands.remote_mac_est_s, 'rerun_s', lands.remote_rerun_s, 'saved_s', lands.remote_saved_s, 't0', lands.remote_t0, 'tests', lands.remote_tests, 'fresh', CASE lands.remote_fresh WHEN 1 THEN json('true') WHEN 0 THEN json('false') END) END, 'wait_s', lands.pre_run_wait_s, 'run_s', lands.pre_run_run_s, 'limit_s', lands.pre_run_limit_s, 'cpu_s', lands.pre_run_cpu_s, 'workers', lands.pre_run_workers) END, 'red_cause', CASE WHEN coalesce(lands.red_class, lands.red_rule, (SELECT 1 FROM land_lists c WHERE c.queue = lands.queue AND c.run = lands.run AND c.kind = 'red_test' LIMIT 1)) IS NOT NULL THEN json_object('cause', lands.red_class, 'rule', lands.red_rule, 'tests', json(nullif(nullif((SELECT json_group_array(c.value ORDER BY c.ord) FROM land_lists c WHERE c.queue = lands.queue AND c.run = lands.run AND c.kind = 'red_test'), '[]'), '{}'))) END, 'diffcov_item', CASE WHEN coalesce(lands.diffcov_item, lands.diffcov_said) IS NOT NULL THEN json_object('id', lands.diffcov_item, 'said', lands.diffcov_said) END, 'cov_risk', CASE WHEN coalesce(lands.cov_said, lands.cov_head, lands.cov_base, lands.cov_lines, (SELECT 1 FROM land_cov_carry c WHERE c.queue = lands.queue AND c.run = lands.run LIMIT 1), (SELECT 1 FROM land_cov_files c WHERE c.queue = lands.queue AND c.run = lands.run LIMIT 1)) IS NOT NULL THEN json_object('said', lands.cov_said, 'head', lands.cov_head, 'base', lands.cov_base, 'lines', lands.cov_lines, 'carry', json(nullif(nullif((SELECT json_group_array(json_patch('{}', json_object('file', c.file, 'text', c.text, 'why', c.why, 'line', c.line, 'own', CASE c.own WHEN 1 THEN json('true') WHEN 0 THEN json('false') END, 'measured', CASE c.measured WHEN 1 THEN json('true') WHEN 0 THEN json('false') END)) ORDER BY c.ord) FROM land_cov_carry c WHERE c.queue = lands.queue AND c.run = lands.run), '[]'), '{}')), 'files', json(nullif(nullif((SELECT json_group_object(c.path, c.said) FROM land_cov_files c WHERE c.queue = lands.queue AND c.run = lands.run), '[]'), '{}'))) END, 'pre_s', lands.pre_s, 'slot_s', lands.slot_s, 'slot_wait_s', lands.slot_wait_s, 'load_start', lands.load_start, 'load_end', lands.load_end, 'slot_wait_by_class', CASE WHEN coalesce(lands.slot_wait_short_s, lands.slot_wait_land_s, lands.slot_wait_pre_s, lands.slot_wait_work_s) IS NOT NULL THEN json_object('short', lands.slot_wait_short_s, 'land', lands.slot_wait_land_s, 'pre', lands.slot_wait_pre_s, 'work', lands.slot_wait_work_s) END, 'early', CASE lands.early WHEN 1 THEN json('true') WHEN 0 THEN json('false') END, 'recorded', CASE lands.recorded WHEN 1 THEN json('true') WHEN 0 THEN json('false') END, 'guards', json(nullif(nullif((SELECT json_group_array(c.value ORDER BY c.ord) FROM land_lists c WHERE c.queue = lands.queue AND c.run = lands.run AND c.kind = 'guard'), '[]'), '{}')), 'red_logs', json(nullif(nullif((SELECT json_group_array(c.value ORDER BY c.ord) FROM land_lists c WHERE c.queue = lands.queue AND c.run = lands.run AND c.kind = 'red_log'), '[]'), '{}')), 'flakes', json(nullif(nullif((SELECT json_group_array(json_patch('{}', json_object('test', c.test, 'entry', c.entry, 'filed', c.filed)) ORDER BY c.ord) FROM land_flakes c WHERE c.queue = lands.queue AND c.run = lands.run), '[]'), '{}')), 'remote_shares', json(nullif(nullif((SELECT json_group_array(json_patch('{}', json_object('host', c.host, 'outcome', c.outcome, 'where', c.place, 'mac_est_s', c.mac_est_s, 'mac_s', c.mac_s, 'rerun_s', c.rerun_s, 'saved_s', c.saved_s, 't0', c.t0, 'worker_s', c.worker_s, 'tests', c.tests)) ORDER BY c.ord) FROM land_remote_shares c WHERE c.queue = lands.queue AND c.run = lands.run), '[]'), '{}')), 'guard', (SELECT value FROM land_lists c WHERE c.queue=lands.queue AND c.run=lands.run AND c.kind='guard' AND c.ord=0), 'at', strftime('%Y-%m-%dT%H:%M:%SZ', lands.at, 'unixepoch'))), coalesce(lands.rest, '{}')) END AS body FROM lands;
